        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);ready(c);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.hurtServer(v.overworld(),p.damageSources().generic(),1);check(p.getHealth()<20,"Air source cannot grant damage immunity");});c.waitFor(v->v.player.getHealth()<20&&v.player.hurtTime>0);noAir(c,"Real damage wins over air source");c.takeScreenshot("air-bow-real-hurt-exit");c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->v.player.onGround());
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);ready(c);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.IRON_CHESTPLATE));p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.CHEST).is(net.minecraft.world.item.Items.IRON_CHESTPLATE));noAir(c,"Actual armor retains native body");c.takeScreenshot("air-bow-real-armor-owner");c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->v.player.onGround());
