        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);ready(c);c.runOnClient(v->{v.player.setXRot(15);v.player.setYRot(25);});c.waitTicks(1);c.takeScreenshot("air-bow-native-independent-look");c.setScreen(()->new net.minecraft.client.gui.screens.PauseScreen(true));c.waitFor(v->v.isPaused());check(c.computeOnClient(v->v.player.isUsingItem()&&frame(v)!=null&&frame(v).clip().equals("bow_air_hold_empty_L")),"Actual native paused air use keeps source");float paused=c.computeOnClient(v->frame(v).time());c.waitTicks(12);check(c.computeOnClient(v->frame(v)!=null&&Math.abs(frame(v).time()-paused)<.000001),"Real pause freezes source hold without a new skill clock");c.takeScreenshot("air-bow-real-pause-clock");c.setScreen(()->null);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->v.player.onGround());
