        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);ready(c);c.getInput().holdKey(WildcraftBindings.CLIMB);c.waitFor(v->dev.wildcraft.traversal.Climbing.intent(v.player).held());noAir(c,"Real G exploration intent owns body even though using bow cannot enter qualified empty-hand climbing");c.takeScreenshot("air-bow-real-climb-intent-only-exit");c.getInput().releaseKey(WildcraftBindings.CLIMB);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->v.player.onGround());
        System.out.println("C6Q real natural jump/default automatic Focus/use, wide-slim/mainLEFT-offMAINRIGHT, native pull/three sprites/real nock/source mask-head-lengths/GPU and waist/legs/root, one real arrow/ammo/wear and actual lease restoration, real 10FPS/manual-confirm/disabled20TPS/natural landing/menu/hurt/armor/occupied exits native head/look/pause/selected-slot zero-effects/RIGHT derived AIR PASS; advanced lifecycle still pending");
